     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.model.Document;
     4	import com.pousadamarealta.model.GuestIdentification;
     5	import com.pousadamarealta.model.Reservation;
     6	import com.pousadamarealta.model.Room;
     7	
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.time.format.DateTimeFormatter;
    11	
    12	public class DocumentGenerator {
    13	    private final PricingService pricingService;
    14	    private static final DateTimeFormatter PT_DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    15	    private static final DateTimeFormatter EN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    16	
    17	    public DocumentGenerator(PricingService pricingService) {
    18	        this.pricingService = pricingService;
    19	    }
    20	
    21	    public Document generate(Reservation reservation, Room room) {
    22	        BigDecimal issRetained = null;
    23	        String guestCpf = null;
    24	        String companyCnpj = null;
    25	        String companyName = null;
    26	        String guestPassport = null;
    27	        String guestCountry = null;
    28	
    29	        String text = "";
    30	        String title = "";
    31	
    32	        if (reservation.identification instanceof GuestIdentification.CPF cpf) {
    33	            guestCpf = cpf.value;
    34	            title = "Comprovante de reserva";
    35	            text = generatePortugueseReceipt(reservation, room, cpf.value);
    36	        } else if (reservation.identification instanceof GuestIdentification.CNPJ cnpj) {
    37	            companyCnpj = cnpj.value;
    38	            companyName = cnpj.companyName;
    39	            title = "Fatura de hospedagem";
    40	            issRetained = pricingService.calculateIssRetention(reservation.total);
    41	            text = generateInvoice(reservation, room, cnpj.value, cnpj.companyName, issRetained);
    42	        } else if (reservation.identification instanceof GuestIdentification.Passport passport) {
    43	            guestPassport = passport.number;
    44	            guestCountry = passport.country;
    45	            title = "Booking receipt";
    46	            text = generateBookingReceipt(reservation, room, passport.number, passport.country);
    47	        }
    48	
    49	        return new Document(title, reservation.id, reservation.guestName, guestCpf,
    50	                           companyCnpj, companyName, guestPassport, guestCountry,
    51	                           room.number, room.type, reservation.checkIn, reservation.checkOut,
    52	                           reservation.nights, reservation.subtotal, reservation.discount,
    53	                           reservation.total, text, issRetained);
    54	    }
    55	
    56	    private String generatePortugueseReceipt(Reservation reservation, Room room, String cpf) {
    57	        String nightsLabel = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
    58	        String discountLine = reservation.discount.compareTo(BigDecimal.ZERO) > 0
    59	                ? String.format("Desconto: R$ %s\n", formatMoney(reservation.discount))
    60	                : "";
    61	
    62	        return String.format("Comprovante de reserva nº %d\n" +
    63	                "Hóspede: %s (CPF %s)\n" +
    64	                "Quarto: %d (%s)\n" +
    65	                "Entrada: %s | Saída: %s | %s\n" +
    66	                "Diárias: R$ %s\n" +
    67	                "%sTotal: R$ %s",
    68	                reservation.id, reservation.guestName, cpf, room.number, room.type,
    69	                reservation.checkIn.format(PT_DATE_FORMAT), reservation.checkOut.format(PT_DATE_FORMAT),
    70	                nightsLabel, formatMoney(reservation.subtotal), discountLine,
    71	                formatMoney(reservation.total));
    72	    }
    73	
    74	    private String generateInvoice(Reservation reservation, Room room, String cnpj, String companyName, BigDecimal issRetained) {
    75	        String nightsLabel = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
    76	        String discountLine = reservation.discount.compareTo(BigDecimal.ZERO) > 0
    77	                ? String.format("Desconto: R$ %s\n", formatMoney(reservation.discount))
    78	                : "";
    79	
    80	        return String.format("Fatura de hospedagem nº %d\n" +
    81	                "Empresa: %s (CNPJ %s)\n" +
    82	                "Hóspede: %s\n" +
    83	                "Quarto: %d (%s)\n" +
    84	                "Entrada: %s | Saída: %s | %s\n" +
    85	                "Diárias: R$ %s\n" +
    86	                "%sTotal: R$ %s\n" +
    87	                "ISS retido (5%%): R$ %s",
    88	                reservation.id, companyName, cnpj, reservation.guestName, room.number, room.type,
    89	                reservation.checkIn.format(PT_DATE_FORMAT), reservation.checkOut.format(PT_DATE_FORMAT),
    90	                nightsLabel, formatMoney(reservation.subtotal), discountLine,
    91	                formatMoney(reservation.total), formatMoney(issRetained));
    92	    }
    93	
    94	    private String generateBookingReceipt(Reservation reservation, Room room, String passportNumber, String country) {
    95	        String nightsLabel = reservation.nights == 1 ? "1 night" : reservation.nights + " nights";
    96	        String discountLine = reservation.discount.compareTo(BigDecimal.ZERO) > 0
    97	                ? String.format("Discount: BRL %s\n", formatMoneyEnglish(reservation.discount))
    98	                : "";
    99	
   100	        return String.format("Booking receipt no. %d\n" +
   101	                "Guest: %s (passport %s, %s)\n" +
   102	                "Room: %d (%s)\n" +
   103	                "Check-in: %s | Check-out: %s | %s\n" +
   104	                "Nights: BRL %s\n" +
   105	                "%sTotal: BRL %s",
   106	                reservation.id, reservation.guestName, passportNumber, country,
   107	                room.number, room.type,
   108	                reservation.checkIn.format(EN_DATE_FORMAT), reservation.checkOut.format(EN_DATE_FORMAT),
   109	                nightsLabel, formatMoneyEnglish(reservation.subtotal), discountLine,
   110	                formatMoneyEnglish(reservation.total));
   111	    }
   112	
   113	    private String formatMoney(BigDecimal value) {
   114	        long integerPart = value.longValue();
   115	        int decimalPart = value.remainder(BigDecimal.ONE).multiply(BigDecimal.valueOf(100)).intValue();
   116	        String formatted = String.format("%,d", integerPart).replace(',', '.');
   117	        return String.format("%s,%02d", formatted, decimalPart);
   118	    }
   119	
   120	    private String formatMoneyEnglish(BigDecimal value) {
   121	        return String.format("%.2f", value);
   122	    }
   123	}
