     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.model.GuestIdentification;
     4	import com.pousadamarealta.model.Message;
     5	import com.pousadamarealta.model.Reservation;
     6	import com.pousadamarealta.model.Room;
     7	import com.pousadamarealta.repository.Repository;
     8	
     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	
    12	public class ReservationService {
    13	    private final Repository repository;
    14	    private final PricingService pricingService;
    15	    private final DocumentGenerator documentGenerator;
    16	
    17	    public ReservationService(Repository repository, PricingService pricingService, DocumentGenerator documentGenerator) {
    18	        this.repository = repository;
    19	        this.pricingService = pricingService;
    20	        this.documentGenerator = documentGenerator;
    21	    }
    22	
    23	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    24	                                        GuestIdentification identification,
    25	                                        LocalDate checkIn, LocalDate checkOut,
    26	                                        int guests, String ratePlan) throws ReservationException {
    27	        Room room = repository.getRoom(roomNumber);
    28	        if (room == null) {
    29	            throw new ReservationException("ROOM_NOT_FOUND", "Room not found");
    30	        }
    31	
    32	        if (guests < 1 || guests > room.capacity) {
    33	            throw new ReservationException("CAPACITY_EXCEEDED", "Guest count exceeds room capacity or is less than 1");
    34	        }
    35	
    36	        if (!checkIn.isBefore(checkOut)) {
    37	            throw new ReservationException("INVALID_REQUEST", "Check-out must be after check-in");
    38	        }
    39	
    40	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, -1)) {
    41	            throw new ReservationException("ROOM_UNAVAILABLE", "Room is not available for the selected dates");
    42	        }
    43	
    44	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    45	        BigDecimal subtotal = pricingService.calculateSubtotal(room.nightlyRate, checkIn, checkOut);
    46	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    47	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    48	
    49	        int id = repository.getNextReservationId();
    50	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail, identification,
    51	                                                  checkIn, checkOut, guests, Reservation.RatePlan.valueOf(ratePlan),
    52	                                                  nights, subtotal, discount, total);
    53	        repository.saveReservation(reservation);
    54	        return reservation;
    55	    }
    56	
    57	    public Reservation confirmReservation(int id, BigDecimal amountPaid) throws ReservationException {
    58	        Reservation reservation = repository.getReservation(id);
    59	        if (reservation == null) {
    60	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
    61	        }
    62	
    63	        if (reservation.status != Reservation.Status.PENDING) {
    64	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed");
    65	        }
    66	
    67	        reservation.status = Reservation.Status.CONFIRMED;
    68	        reservation.amountPaid = amountPaid;
    69	        repository.saveReservation(reservation);
    70	
    71	        Room room = repository.getRoom(reservation.roomNumber);
    72	        var document = documentGenerator.generate(reservation, room);
    73	        String emailBody = String.format("Olá, %s!\n\nSua reserva na Pousada Maré Alta está confirmada. " +
    74	                "Estes são os dados dela:\n\n%s\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n" +
    75	                "Até breve!", reservation.guestName, document.text);
    76	
    77	        Message message = new Message(repository.getAllMessages().size() + 1, "EMAIL",
    78	                                     reservation.guestEmail, "Reserva confirmada - Pousada Maré Alta", emailBody);
    79	        repository.saveMessage(message);
    80	
    81	        return reservation;
    82	    }
    83	
    84	    public Reservation checkIn(int id) throws ReservationException {
    85	        Reservation reservation = repository.getReservation(id);
    86	        if (reservation == null) {
    87	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
    88	        }
    89	
    90	        if (reservation.status != Reservation.Status.CONFIRMED) {
    91	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Only confirmed reservations can check in");
    92	        }
    93	
    94	        reservation.status = Reservation.Status.CHECKED_IN;
    95	        repository.saveReservation(reservation);
    96	        return reservation;
    97	    }
    98	
    99	    public Reservation checkOut(int id) throws ReservationException {
   100	        Reservation reservation = repository.getReservation(id);
   101	        if (reservation == null) {
   102	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
   103	        }
   104	
   105	        if (reservation.status != Reservation.Status.CHECKED_IN) {
   106	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Only checked-in reservations can check out");
   107	        }
   108	
   109	        reservation.status = Reservation.Status.CHECKED_OUT;
   110	        repository.saveReservation(reservation);
   111	        return reservation;
   112	    }
   113	
   114	    public Reservation cancelReservation(int id) throws ReservationException {
   115	        Reservation reservation = repository.getReservation(id);
   116	        if (reservation == null) {
   117	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
   118	        }
   119	
   120	        if (reservation.status != Reservation.Status.PENDING && reservation.status != Reservation.Status.CONFIRMED) {
   121	            throw new ReservationException("OPERATION_NOT_ALLOWED", "Cannot cancel reservation in current status");
   122	        }
   123	
   124	        if (reservation.ratePlan == Reservation.RatePlan.NON_REFUNDABLE) {
   125	            reservation.refund = BigDecimal.ZERO;
   126	        } else {
   127	            reservation.refund = reservation.amountPaid;
   128	        }
   129	
   130	        reservation.status = Reservation.Status.CANCELLED;
   131	        repository.saveReservation(reservation);
   132	        return reservation;
   133	    }
   134	
   135	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut, int excludeReservationId) {
   136	        LocalDate current = checkIn;
   137	        while (current.isBefore(checkOut)) {
   138	            for (Reservation res : repository.getAllReservations()) {
   139	                if (res.id != excludeReservationId && res.roomNumber == roomNumber &&
   140	                    res.status != Reservation.Status.CANCELLED) {
   141	                    if (!current.isBefore(res.checkIn) && current.isBefore(res.checkOut)) {
   142	                        return true;
   143	                    }
   144	                }
   145	            }
   146	            current = current.plusDays(1);
   147	        }
   148	        return false;
   149	    }
   150	
   151	    public static class ReservationException extends Exception {
   152	        public final String code;
   153	
   154	        public ReservationException(String code, String message) {
   155	            super(message);
   156	            this.code = code;
   157	        }
   158	    }
   159	}

