  3	import java.math.BigDecimal;
  4	import java.math.RoundingMode;
  5	import java.time.LocalDate;
  6	import java.time.YearMonth;
  7	
  8	public class PricingService {
  9	    private static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("1.20");
 10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 11	
 12	    public BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
 13	        if (isHighSeason(date)) {
 14	            return baseRate.multiply(HIGH_SEASON_SURCHARGE).setScale(2, RoundingMode.HALF_EVEN);
 15	        }
 16	        return baseRate;
 17	    }
 18	
 19	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
 20	        BigDecimal total = BigDecimal.ZERO;
 21	        LocalDate current = checkIn;
 22	        while (current.isBefore(checkOut)) {
 23	            total = total.add(calculateNightlyRate(baseRate, current));
 24	            current = current.plusDays(1);
 25	        }
 26	        return total.setScale(2, RoundingMode.HALF_EVEN);
 27	    }
 28	
 29	    public BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
 30	        if ("NON_REFUNDABLE".equals(ratePlan)) {
 31	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
 32	        }
 33	        return BigDecimal.ZERO;
 34	    }
 35	
 36	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 37	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
 38	    }
 39	
 40	    public BigDecimal calculateIssRetention(BigDecimal total) {
 41	        return total.multiply(new BigDecimal("0.05")).setScale(2, RoundingMode.HALF_EVEN);
 42	    }
 43	
 44	    private boolean isHighSeason(LocalDate date) {
 45	        int month = date.getMonthValue();
 46	        int day = date.getDayOfMonth();
 47	
 48	        if (month >= 12) {
 49	            return true;
 50	        }
 51	        if (month <= 2) {
 52	            return true;
 53	        }
 54	        if (month == 7) {
 55	            return true;
 56	        }
 57	        return false;
 58	    }
 59	}
