 44	    private boolean isHighSeason(LocalDate date) {
 45	        int month = date.getMonthValue();
 46	        int day = date.getDayOfMonth();
 47	
 48	        if (month >= 12) {
 49	            return true;
 50	        }
 51	        if (month <= 2) {
 52	            return true;
 53	        }
 54	        if (month == 7) {
 55	            return true;
 56	        }
 57	        return false;
 58	    }
