 80	    public String generateOccupancyReport(LocalDate date) {
 81	        StringBuilder csv = new StringBuilder();
 82	        csv.append("room,type,reservation,check_in,check_out\n");
 83	
 84	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 85	
 86	        List<Reservation> occupiedReservations = repository.getAllReservations().stream()
 87	                .filter(r -> r.status == Reservation.Status.CONFIRMED ||
 88	                            r.status == Reservation.Status.CHECKED_IN ||
 89	                            r.status == Reservation.Status.CHECKED_OUT)
 90	                .filter(r -> !date.isBefore(r.checkIn) && date.isBefore(r.checkOut))
 91	                .sorted(Comparator.comparingInt((Reservation r) -> r.roomNumber)
 92	                       .thenComparingInt(r -> r.id))
 93	                .collect(Collectors.toList());
 94	
 95	        for (Reservation res : occupiedReservations) {
 96	            Room room = repository.getRoom(res.roomNumber);
 97	            csv.append(String.format("%d,%s,%d,%s,%s\n", res.roomNumber, room.type, res.id,
 98	                                    res.checkIn.format(formatter), res.checkOut.format(formatter)));
 99	        }
100	
101	        int totalRooms = repository.getAllRooms().size();
102	        csv.append(String.format("total,%d/%d\n", occupiedReservations.size(), totalRooms));
103	
104	        return csv.toString();
105	    }
106	
107	    public String generateRevenueReport(YearMonth month) {
108	        StringBuilder csv = new StringBuilder();
109	        csv.append("reservation,room,check_in,check_out,status,amount\n");
110	
111	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
112	
113	        List<Reservation> relevantReservations = repository.getAllReservations().stream()
114	                .filter(r -> YearMonth.from(r.checkIn).equals(month))
115	                .filter(r -> r.status == Reservation.Status.CONFIRMED ||
116	                            r.status == Reservation.Status.CHECKED_IN ||
117	                            r.status == Reservation.Status.CHECKED_OUT ||
118	                            r.status == Reservation.Status.CANCELLED)
119	                .sorted(Comparator.comparing((Reservation r) -> r.checkIn)
120	                       .thenComparingInt(r -> r.id))
121	                .collect(Collectors.toList());
122	
123	        BigDecimal totalAmount = BigDecimal.ZERO;
124	
125	        for (Reservation res : relevantReservations) {
126	            BigDecimal amount = res.amountPaid;
127	            if (res.refund != null) {
128	                amount = amount.subtract(res.refund);
129	            }
130	
131	            csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n", res.id, res.roomNumber,
132	                                    res.checkIn.format(formatter), res.checkOut.format(formatter),
133	                                    res.status.name(), amount));
134	            totalAmount = totalAmount.add(amount);
135	        }
136	
137	        csv.append(String.format("total,,,,%.2f\n", totalAmount));
138	
139	        return csv.toString();
140	    }
